```t
t 0
task abs(x: int) returns (r: int)
  ensures r >= 0
  ensures r == x or r == -x
{
  if x < 0 {
    r := -x;
  } else {
    r := x;
  }
}
```

```t
t 0
task max(x: int, y: int) returns (r: int)
  ensures r >= x
  ensures r >= y
  ensures r == x or r == y
{
  if x >= y {
    r := x;
  } else {
    r := y;
  }
}
```

```t
t 1
gate loops
task sum_upto(n: int) returns (r: int)
  requires n >= 0
  ensures 2 * r == n * (n + 1)
{
  r := 0;
  var i: int := 0;
  while i < n
    invariant 2 * r == i * (i + 1)
    invariant i >= 0 and i <= n
    decreases n - i
  {
    i := i + 1;
    r := r + i;
  }
}
```

```t
t 1
gate loops
task linear_search(s: seq, x: int) returns (r: int)
  ensures r == -1 or r >= 0 and r < len(s) and s[r] == x
  ensures r == -1 ==> (forall i in [0, len(s)) . s[i] != x)
  ensures r != -1 ==> (forall i in [0, r) . i < len(s) ==> s[i] != x)
{
  r := -1;
  var i: int := 0;
  while i < len(s) and r == -1
    invariant r == -1 ==> (forall j in [0, i) . j < len(s) ==> s[j] != x)
    invariant r != -1 ==> r >= 0 and r < len(s) and s[r] == x and (forall j in [0, r) . j < len(s) ==> s[j] != x)
    invariant i >= 0 and i <= len(s)
    decreases len(s) - i
  {
    if s[i] == x {
      r := i;
    } else {
    }
    i := i + 1;
  }
}
```

```t
t 1
gate recursion
task gcd(a: int, b: int) returns (r: int)
  requires a >= 0
  requires b >= 0
  ensures r == gcds(a, b)
  decreases a + b
spec fun gcds(a: int, b: int): int
  decreases a + b
= if a <= 0 then b else if b <= 0 then a else if a > b then gcds(a - b, b) else if b > a then gcds(a, b - a) else a
{
  if a == 0 {
    r := b;
  } else {
    if b == 0 {
      r := a;
    } else {
      if a > b {
        r := gcd(a - b, b);
      } else {
        if b > a {
          r := gcd(a, b - a);
        } else {
          r := a;
        }
      }
    }
  }
}
```

